// Design tokens for the 5 Slides in 5 Minutes library.
// Slide stage: 13.333in x 7.5in (PowerPoint LAYOUT_WIDE). All coordinates are inches.

const STAGE = { w: 13.333, h: 7.5, margin: 0.75 };

// Font roles. PowerPoint uses Bahnschrift (system DIN, ships with Windows) so Eric can
// edit on any machine; HTML embeds the Baylor DIN Pro files from Baylor_Fonts.
const FONTS = {
  body:      { pptx: "Bahnschrift",                   css: "'DIN Pro', 'Bahnschrift', sans-serif", weight: 400 },
  light:     { pptx: "Bahnschrift Light",             css: "'DIN Pro', 'Bahnschrift', sans-serif", weight: 300 },
  medium:    { pptx: "Bahnschrift SemiBold",          css: "'DIN Pro', 'Bahnschrift', sans-serif", weight: 500 },
  cond:      { pptx: "Bahnschrift Condensed",         css: "'DIN Pro Condensed', 'Bahnschrift Condensed', sans-serif", weight: 400 },
  condLight: { pptx: "Bahnschrift Light Condensed",   css: "'DIN Pro Condensed', 'Bahnschrift Condensed', sans-serif", weight: 300 },
  condBold:  { pptx: "Bahnschrift SemiBold Condensed", css: "'DIN Pro Condensed', 'Bahnschrift Condensed', sans-serif", weight: 700 },
};

// Palettes. Each has a dark mode (slides 1, 3, 5) and a light mode (slides 2, 4).
// Roles: bg ground, ink primary text, muted secondary text (>=4.5:1 on bg),
// accent = the one emphasis colour (text-safe on its own ground), shape = data/graphic
// fill (>=3:1 on bg), soft = quiet secondary fill, rule = hairlines.
const PALETTES = {
