// Render a built deck to one self-contained, offline HTML file.

const fs = require("fs");
const path = require("path");
const { FONTS, STAGE } = require("./tokens");
const { chrome } = require("./chrome");
const { smoothToBeziers } = require("./geometry");

const PX = 96;               // px per inch: stage is 1280 x 720
const W = STAGE.w * PX, H = STAGE.h * PX;
const LINE_BOX = 1.2;        // PowerPoint's line spacing multiple is relative to ~1.2em

const FONT_FILES = [
  ["DIN Pro", 300, "din-light"], ["DIN Pro", 400, "din-regular"], ["DIN Pro", 500, "din-medium"],
  ["DIN Pro Condensed", 300, "dinc-light"], ["DIN Pro Condensed", 400, "dinc-regular"],
  ["DIN Pro Condensed", 500, "dinc-medium"], ["DIN Pro Condensed", 700, "dinc-bold"],
];

let fontCss = null;
function fontFaces() {
  if (fontCss) return fontCss;
  fontCss = FONT_FILES.map(([fam, wt, file]) => {
    const b64 = fs.readFileSync(path.join(__dirname, "fonts", `${file}.woff2`)).toString("base64");
    return `@font-face{font-family:'${fam}';font-weight:${wt};font-style:normal;font-display:block;src:url(data:font/woff2;base64,${b64}) format('woff2')}`;
  }).join("\n");
  return fontCss;
}

const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const n = v => +(v * PX).toFixed(2);
const pt = v => +((v * PX) / 72).toFixed(2);
const hex = c => (c ? `#${c}` : "none");

function svgShape(it) {
  switch (it.t) {
    case "rect":
      return `<rect x="${n(it.x)}" y="${n(it.y)}" width="${n(it.w)}" height="${n(it.h)}" fill="${hex(it.fill)}" fill-opacity="${it.opacity}"${it.line ? ` stroke="${hex(it.line)}" stroke-width="${pt(it.lineW)}"${it.dash ? ' stroke-dasharray="6 4"' : ""}` : ""}/>`;
    case "ellipse":
      return `<ellipse cx="${n(it.x + it.w / 2)}" cy="${n(it.y + it.h / 2)}" rx="${n(it.w / 2)}" ry="${n(it.h / 2)}" fill="${hex(it.fill)}" fill-opacity="${it.opacity}"${it.line ? ` stroke="${hex(it.line)}" stroke-width="${pt(it.lineW)}"` : ""}/>`;
    case "line": {
      const mk = it.arrow ? `marker-end` : "";
      const id = `a${it.color}`;
      const ends = [];
      if (it.arrow === "end" || it.arrow === "both") ends.push(`marker-end="url(#${id})"`);
      if (it.arrow === "start" || it.arrow === "both") ends.push(`marker-start="url(#${id}s)"`);
      void mk;
      return `<line x1="${n(it.x1)}" y1="${n(it.y1)}" x2="${n(it.x2)}" y2="${n(it.y2)}" stroke="${hex(it.color)}" stroke-width="${pt(it.w)}"${it.dash ? ' stroke-dasharray="7 5"' : ""} ${ends.join(" ")}/>`;
    }
    case "arc": {
      const r1 = it.r, r0 = it.r - it.thick;
      const pt2 = (r, a) => { const rad = ((a - 90) * Math.PI) / 180; return [n(it.cx + r * Math.cos(rad)), n(it.cy + r * Math.sin(rad))]; };
      let sweep = (((it.end - it.start) % 360) + 360) % 360; if (sweep === 0) sweep = 359.99;
      const large = sweep > 180 ? 1 : 0;
      const end = it.start + sweep;
      const [ax, ay] = pt2(r1, it.start), [bx, by] = pt2(r1, end), [cx, cy] = pt2(r0, end), [dx, dy] = pt2(r0, it.start);
      return `<path d="M${ax} ${ay} A${n(r1)} ${n(r1)} 0 ${large} 1 ${bx} ${by} L${cx} ${cy} A${n(r0)} ${n(r0)} 0 ${large} 0 ${dx} ${dy}Z" fill="${hex(it.color)}"/>`;
    }
    case "path": {
      let d = `M${n(it.points[0][0])} ${n(it.points[0][1])}`;
      if (it.smooth) {
        for (const s of smoothToBeziers(it.points)) d += ` C${n(s.c1[0])} ${n(s.c1[1])} ${n(s.c2[0])} ${n(s.c2[1])} ${n(s.to[0])} ${n(s.to[1])}`;
      } else {
        for (const p of it.points.slice(1)) d += ` L${n(p[0])} ${n(p[1])}`;
      }
      if (it.fill) d += "Z";
      const stroke = it.fill && !it.w ? "" : ` stroke="${hex(it.color)}" stroke-width="${pt(it.w)}" stroke-linejoin="round" stroke-linecap="round"${it.dash ? ' stroke-dasharray="8 6"' : ""}`;
      return `<path d="${d}" fill="${it.fill ? hex(it.fill) : "none"}" fill-opacity="${it.opacity}"${stroke}/>`;
    }
  }
  return "";
}

function markerDefs(items) {
  const colors = [...new Set(items.filter(i => i.t === "line" && i.arrow).map(i => i.color))];
  if (!colors.length) return "";
  return `<defs>${colors.map(c => `<marker id="a${c}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10z" fill="#${c}"/></marker><marker id="a${c}s" viewBox="0 0 10 10" refX="2" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#${c}"/></marker>`).join("")}</defs>`;
}

function textDiv(it) {
  const f = FONTS[it.font];
  const just = it.valign === "bottom" ? "flex-end" : it.valign === "middle" ? "center" : "flex-start";
  const style = [
    `left:${n(it.x)}px`, `top:${n(it.y)}px`, `width:${n(it.w)}px`, `height:${n(it.h)}px`,
    `justify-content:${just}`, `text-align:${it.align}`,
    `font-family:${f.css}`, `font-weight:${f.weight}`, `font-size:${pt(it.size)}px`,
    `line-height:${(it.lineH * LINE_BOX).toFixed(3)}`, `color:#${it.color}`,
    it.tracking ? `letter-spacing:${pt(it.tracking)}px` : "", it.caps ? "text-transform:uppercase" : "",
    it.italic ? "font-style:italic" : "",
  ].filter(Boolean).join(";");
  const inner = it.runs.map(r => {
    const t = esc(r.t).replace(/\n/g, "<br>");
    const st = [];
    if (r.color) st.push(`color:#${r.color}`);
    if (r.font) { const rf = FONTS[r.font]; st.push(`font-family:${rf.css}`, `font-weight:${rf.weight}`); }
    if (r.size) st.push(`font-size:${pt(r.size)}px`);
    return st.length ? `<span style="${st.join(";")}">${t}</span>` : t;
  }).join("");
  const tag = it.role === "headline" ? "h2" : "p";
  return `<div class="t" style="${style}"><${tag}>${inner}</${tag}></div>`;
}

function slideHtml(deck, sl, i) {
  const items = [...sl.scene.items, ...chrome(deck, i, sl.scene)];
  let out = "";
  let shapes = [];
  const flush = () => {
    if (!shapes.length) return;
    out += `<svg class="g" viewBox="0 0 ${W} ${H}" aria-hidden="true">${markerDefs(shapes)}${shapes.map(svgShape).join("")}</svg>`;
    shapes = [];
  };
  for (const it of items) {
    if (it.t === "text") { flush(); out += textDiv(it); } else shapes.push(it);
  }
  flush();
  return `<section class="slide ${sl.mode}" style="background:#${sl.scene.P.bg}" data-n="${i + 1}" aria-label="Slide ${i + 1} of 5: ${sl.roleName}" aria-roledescription="slide">${out}</section>`;
}

function renderHtml(deck) {
  const m = deck.meta;
  const notes = deck.slides.map((sl, i) => `<div class="note" data-n="${i + 1}"><h3>${i + 1}. ${sl.roleName}${sl.time ? ` <span>~${sl.time}s</span>` : ""}</h3>${String(sl.notes || "").split(/\n\s*\n/).map(p => `<p>${esc(p).replace(/\n/g, "<br>")}</p>`).join("")}</div>`).join("");
  const bg0 = deck.palette.dark.bg;
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(m.title)} · 5 Slides in 5 Minutes</title>
<meta name="description" content="${esc(m.title)}: a five-minute Performance School deck from Baylor Athletics Applied Performance.">
<style>
${fontFaces()}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{background:#0c0f0e;color:#e9ece9;font-family:'DIN Pro','Bahnschrift',sans-serif;overflow:hidden}
.viewport{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}
.stage{position:relative;width:${W}px;height:${H}px;flex:none;transform-origin:center center;background:#${bg0}}
.slide{position:absolute;inset:0;overflow:hidden;visibility:hidden;opacity:0}
.slide.on{visibility:visible;opacity:1}
@media (prefers-reduced-motion:no-preference){.slide{transition:opacity .28s cubic-bezier(.16,1,.3,1),visibility 0s linear .28s}.slide.on{transition:opacity .28s cubic-bezier(.16,1,.3,1),visibility 0s}}
.g{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.t{position:absolute;display:flex;flex-direction:column;overflow:visible;font-kerning:normal;font-variant-numeric:lining-nums}
.t h2,.t p{font:inherit;margin:0}
.hud{position:fixed;right:16px;bottom:12px;display:flex;gap:6px;align-items:center;font-size:13px;color:#9aa69f;opacity:.0;transition:opacity .3s}
body:hover .hud,.hud:focus-within{opacity:1}
.hud button{background:#1b2420;color:#dfe6e1;border:1px solid #33423c;border-radius:4px;min-width:36px;height:32px;font:inherit;cursor:pointer}
.hud button:hover{background:#25322c}
.hud button:focus-visible{outline:2px solid #FFB81C;outline-offset:2px}
.notes{display:none}
body.presenter .viewport{right:min(36vw,520px)}
body.presenter .notes{display:block;position:fixed;top:0;right:0;bottom:0;width:min(36vw,520px);background:#121816;border-left:1px solid #2a3531;padding:28px 28px 80px;overflow:auto}
.notes .clock{font-family:'DIN Pro Condensed',sans-serif;font-size:44px;font-weight:300;color:#FFB81C;letter-spacing:.02em;margin-bottom:18px}
.notes .note{display:none}.notes .note.on{display:block}
.notes h3{font-family:'DIN Pro Condensed',sans-serif;font-weight:500;font-size:20px;letter-spacing:.06em;text-transform:uppercase;color:#cfe3d7;margin-bottom:12px}
.notes h3 span{color:#8fa79a;font-weight:400}
.notes p{font-size:18px;line-height:1.5;color:#e4ebe6;margin-bottom:12px;max-width:62ch}
.notes .help{font-size:13px;color:#8fa79a;margin-top:24px}
@page{size:${STAGE.w}in ${STAGE.h}in;margin:0}
@media print{
  html,body{height:auto;overflow:visible;background:none}
  .viewport{position:static;display:block}
  .stage{transform:none!important;width:${STAGE.w}in;height:auto;background:none}
  .slide{position:relative;visibility:visible;opacity:1;width:${W}px;height:${H}px;break-after:page;-webkit-print-color-adjust:exact;print-color-adjust:exact}
  .hud,.notes{display:none!important}
}
</style>
</head>
<body>
<div class="viewport"><main class="stage" id="stage" aria-label="${esc(m.title)}" aria-roledescription="slide deck">
${deck.slides.map((sl, i) => slideHtml(deck, sl, i)).join("\n")}
</main></div>
<aside class="notes" aria-label="Presenter notes"><div class="clock" id="clock">0:00</div>${notes}<p class="help">Arrows, Space or click to move · P presenter view · F full screen · Home/End jump · R resets the clock</p></aside>
<nav class="hud" aria-label="Deck controls"><button id="prev" aria-label="Previous slide">&larr;</button><span id="count" aria-live="polite">1 / 5</span><button id="next" aria-label="Next slide">&rarr;</button><button id="pres" aria-label="Toggle presenter view">P</button></nav>
<script>
(function(){
  var slides=[].slice.call(document.querySelectorAll('.slide')),notes=[].slice.call(document.querySelectorAll('.note'));
  var stage=document.getElementById('stage'),count=document.getElementById('count'),i=0;
  var start=parseInt((location.hash||'').replace('#',''),10);if(start>=1&&start<=slides.length)i=start-1;
  function fit(){var vp=stage.parentNode.getBoundingClientRect();var s=Math.min(vp.width/${W},vp.height/${H});stage.style.transform='scale('+s+')';}
  function show(k){i=Math.max(0,Math.min(slides.length-1,k));slides.forEach(function(s,j){s.classList.toggle('on',j===i);s.setAttribute('aria-hidden',j===i?'false':'true');});notes.forEach(function(n,j){n.classList.toggle('on',j===i);});count.textContent=(i+1)+' / '+slides.length;history.replaceState(null,'','#'+(i+1));}
  var t0=Date.now();setInterval(function(){var s=Math.floor((Date.now()-t0)/1000);document.getElementById('clock').textContent=Math.floor(s/60)+':'+('0'+s%60).slice(-2);},500);
  function togglePres(){document.body.classList.toggle('presenter');fit();}
  document.addEventListener('keydown',function(e){
    if(e.metaKey||e.ctrlKey||e.altKey)return;
    var k=e.key;
    if(k==='ArrowRight'||k==='PageDown'||k===' '||k==='Enter'){e.preventDefault();show(i+1);}
    else if(k==='ArrowLeft'||k==='PageUp'||k==='Backspace'){e.preventDefault();show(i-1);}
    else if(k==='Home'){show(0);}else if(k==='End'){show(slides.length-1);}
    else if(k==='p'||k==='P'){togglePres();}
    else if(k==='r'||k==='R'){t0=Date.now();}
    else if(k==='f'||k==='F'){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen&&document.documentElement.requestFullscreen();}
  });
  stage.addEventListener('click',function(e){var r=stage.getBoundingClientRect();show(e.clientX<r.left+r.width/3?i-1:i+1);});
  document.getElementById('prev').onclick=function(){show(i-1);};document.getElementById('next').onclick=function(){show(i+1);};document.getElementById('pres').onclick=togglePres;
  window.addEventListener('resize',fit);fit();show(i);
})();
</script>
</body>
</html>
`;
}

module.exports = { renderHtml };

