      const links = [
        ["deck.html", "Present"], ["deck.pptx", "PowerPoint"], ["deck.pdf", "PDF"], ["notes.md", "Notes & sources"],
      ].filter(([f]) => exists(m.dir, f)).map(([f, l]) => `<a href="${m.dir}/${f}">${l}</a>`).join("");
      return `<li class="deck"><a class="cover" href="${m.dir}/deck.html" aria-label="Present ${esc(m.title)}">${thumb}</a><div class="meta"><span class="num">${num}</span><h3><a href="${m.dir}/deck.html">${esc(m.title)}</a></h3></div><p class="idea">${esc(m.oneIdea || "")}</p><nav class="links" aria-label="${esc(m.title)} files">${links}</nav></li>`;
