:root{--bg:#F4F2EC;--ink:#0B2A1F;--muted:#4E5150;--rule:#D9D5C6;--green:#154734;--gold:#FFB81C;--antique:#7A6420}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0B2A1F;--ink:#F4F2EC;--muted:#AFD2C0;--rule:#2E5C49;--green:#AFD2C0;--antique:#E3C26A}}
:root[data-theme="dark"]{--bg:#0B2A1F;--ink:#F4F2EC;--muted:#AFD2C0;--rule:#2E5C49;--green:#AFD2C0;--antique:#E3C26A}
*{box-sizing:border-box;margin:0;padding:0}
body{background:var(--bg);color:var(--ink);font-family:'Bahnschrift','DIN Pro','Segoe UI',sans-serif;line-height:1.45}
header{max-width:1240px;margin:0 auto;padding:72px 24px 40px;display:grid;gap:18px}
header h1{font-family:'Bahnschrift Condensed','DIN Pro Condensed','Bahnschrift',sans-serif;font-weight:700;font-size:clamp(40px,7vw,84px);line-height:.95;letter-spacing:-.01em}
header p{font-size:19px;color:var(--muted);max-width:60ch}
header .by{font-size:14px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
main{max-width:1240px;margin:0 auto;padding:0 24px 96px}
.cat{padding-top:56px}
.cat h2{font-family:'Bahnschrift Condensed','DIN Pro Condensed',sans-serif;font-weight:600;font-size:26px;padding-bottom:12px;border-bottom:1px solid var(--rule);margin-bottom:24px}
.grid{list-style:none;display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:36px 28px}
.cover{display:block;aspect-ratio:16/9;background:var(--rule);overflow:hidden}
.cover img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s cubic-bezier(.16,1,.3,1)}
.cover:hover img{transform:scale(1.03)}
.nothumb{display:block;width:100%;height:100%}
.meta{display:flex;gap:10px;align-items:baseline;margin-top:14px}
.num{font-family:'Bahnschrift Condensed',sans-serif;color:var(--antique);font-size:15px;font-variant-numeric:tabular-nums}
.deck h3{font-size:19px;font-weight:600;line-height:1.2}
.deck h3 a{color:inherit;text-decoration:none}
.deck h3 a:hover{text-decoration:underline;text-underline-offset:3px}
.idea{font-size:15px;color:var(--muted);margin-top:6px}
.links{display:flex;flex-wrap:wrap;gap:4px 14px;margin-top:10px;font-size:14px}
.links a{color:var(--green);text-underline-offset:3px}
a:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
footer{max-width:1240px;margin:0 auto;padding:24px;border-top:1px solid var(--rule);font-size:14px;color:var(--muted)}
</style>
</head>
<body>
<header>
<span class="by">Baylor Athletics · Applied Performance · Performance School</span>
<h1>5 Slides in 5 Minutes</h1>
<p>${metas.length} five-minute decks for staff across the department. Each one makes one point, backs it with sources, and ends on a question for the room.</p>
</header>
<main>
${sections}
</main>
<footer>Each deck opens as a presentation (arrow keys to move, P for presenter notes). The PowerPoint files are fully editable. Sources for every figure are in each deck's notes.</footer>
</body>
</html>
`;
  fs.writeFileSync(path.join(root, "index.html"), html);
}

module.exports = { writeGallery, CATEGORIES };

