.num{font-family:'Bahnschrift Condensed',sans-serif;color:var(--antique);font-size:15px;font-variant-numeric:tabular-nums}
.deck h3{font-size:19px;font-weight:600;line-height:1.2}
.deck h3 a{color:inherit;text-decoration:none}
.deck h3 a:hover{text-decoration:underline;text-underline-offset:3px}
.idea{font-size:15px;color:var(--muted);margin-top:6px}
.links{display:flex;flex-wrap:wrap;gap:4px 14px;margin-top:10px;font-size:14px}
.links a{color:var(--green);text-underline-offset:3px}
a:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
footer{max-width:1240px;margin:0 auto;padding:24px;border-top:1px solid var(--rule);font-size:14px;color:var(--muted)}
</style>
</head>
<body>
<header>
<span class="by">Baylor Athletics · Applied Performance · Performance School</span>
<h1>5 Slides in 5 Minutes</h1>
<p>${metas.length} five-minute decks for staff across the department. Each one makes one point, backs it with sources, and ends on a question for the room.</p>
</header>
<main>
${sections}
</main>
<footer>Each deck opens as a presentation (arrow keys to move, P for presenter notes). The PowerPoint files are fully editable. Sources for every figure are in each deck's notes.</footer>
</body>
</html>
`;
  fs.writeFileSync(path.join(root, "index.html"), html);
}

module.exports = { writeGallery, CATEGORIES };

# Export decks through PowerPoint: deck.pdf, png/slide1..5.png (QA renders) and thumb.png.
# Usage: pwsh -NoProfile -File scripts/export.ps1 [06 12 ...]   (no args = every deck)
param([string[]]$Decks)

$root = Join-Path $PSScriptRoot "..\decks" | Resolve-Path
$dirs = Get-ChildItem $root -Directory | Where-Object { $_.Name -match '^\d\d-' -and (Test-Path (Join-Path $_.FullName 'deck.pptx')) }
if ($Decks) { $dirs = $dirs | Where-Object { $n = $_.Name; $Decks | Where-Object { $n.StartsWith($_.PadLeft(2, '0')) } } }

$app = New-Object -ComObject PowerPoint.Application
try {
  foreach ($d in $dirs) {
    $pptx = Join-Path $d.FullName 'deck.pptx'
    $pres = $app.Presentations.Open($pptx, $true, $false, $false)  # read-only, no window
    try {
      $pres.SaveAs((Join-Path $d.FullName 'deck.pdf'), 32)            # ppSaveAsPDF
      $png = Join-Path $d.FullName 'png'
      New-Item -ItemType Directory -Force $png | Out-Null
      for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $pres.Slides.Item($i).Export((Join-Path $png "slide$i.png"), 'PNG', 1600, 900)
      }
      $pres.Slides.Item(1).Export((Join-Path $d.FullName 'thumb.png'), 'PNG', 800, 450)
      Write-Output "ok   $($d.Name)"
    } finally { $pres.Close() }
  }
} finally {
  $app.Quit()
  [System.Runtime.Interopservices.Marshal]::ReleaseComObject($app) | Out-Null
}

