#!/usr/bin/env node
// HTML QA: node scripts/qa.js [all | 06 ...]
// Measures text overflow in the browser and screenshots each HTML slide to
// decks/NN-slug/png/html-slideN.png at 1280x720 (headless Chrome).

const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");
const { pathToFileURL } = require("url");

const CHROME = process.env.CHROME || "C:/Program Files/Google/Chrome/Application/chrome.exe";
const ROOT = path.join(__dirname, "..", "decks");
const args = process.argv.slice(2);
const dirs = fs.readdirSync(ROOT).filter(d => /^\d\d-/.test(d) && fs.existsSync(path.join(ROOT, d, "deck.html")))
  .filter(d => !args.length || args[0] === "all" || args.some(a => d.startsWith(String(a).padStart(2, "0"))));

const base = ["--headless=new", "--disable-gpu", "--hide-scrollbars", "--no-first-run", "--force-device-scale-factor=1", "--run-all-compositor-stages-before-draw", "--virtual-time-budget=4000"];
let problems = 0;
for (const d of dirs) {
  const file = path.join(ROOT, d, "deck.html");
  const url = pathToFileURL(file).href;
  const dom = execFileSync(CHROME, [...base, "--dump-dom", `${url}?qa#1`], { encoding: "utf8", maxBuffer: 64 << 20 });
  const m = dom.match(/<pre id="qa">([\s\S]*?)<\/pre>/);
  const found = m ? JSON.parse(m[1].replace(/&quot;/g, '"').replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")) : null;
  if (!found) { console.log(`FAIL ${d}: QA probe did not run`); problems++; continue; }
  const png = path.join(ROOT, d, "png");
  fs.mkdirSync(png, { recursive: true });
  for (let k = 1; k <= 5; k++) {
    execFileSync(CHROME, [...base, "--window-size=1280,720", `--screenshot=${path.join(png, `html-slide${k}.png`)}`, `${url}#${k}`], { stdio: "ignore" });
  }
  if (found.length) { problems++; found.forEach(f => console.log(`  overflow ${d} slide ${f.slide}: "${f.text}" y+${f.overY}px x+${f.overX}px`)); }
  else console.log(`ok   ${d}`);
}
process.exitCode = problems ? 1 : 0;

