cd /c/Users/eric_rash/Desktop/DEV/Education_Alignment_Initiative/.claude/worktrees/5s5m-library && node -e "
const {PALETTES}=require('./decks/_engine/tokens');
const lum=h=>{const c=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=.03928?v/12.92:((v+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]};
const cr=(a,b)=>{const[x,y]=[lum(a),lum(b)].sort((p,q)=>q-p);return (x+.05)/(y+.05)};
let bad=0;for(const[k,p] of Object.entries(PALETTES))for(const m of ['dark','light']){const t=p[m];const r={ink:cr(t.ink,t.bg),muted:cr(t.muted,t.bg),accent:cr(t.accent,t.bg),shape:cr(t.shape,t.bg),mutedOnSoft:cr(t.muted,t.soft)};const b=Object.entries(r).filter(([n,v])=>(n=='ink'&&v<7)||((n=='muted'||n=='accent'||n=='mutedOnSoft')&&v<4.5)||(n=='shape'&&v<3));if(b.length){bad++;console.log(k,m,b.map(([n,v])=>n+'='+v.toFixed(2)).join(' '))}}console.log(bad?'issues':'all palettes pass')"

