    dark:  { bg: "154734", ink: "FFFFFF", muted: "CFE3D7", accent: "FFB81C", shape: "FFB81C", soft: "1F5A43", rule: "3A7559" },
    light: { bg: "FFFFFF", ink: "154734", muted: "4E5150", accent: "154734", shape: "154734", soft: "EDF2EE", rule: "D7E0DA" },
  },
