    light: { bg: "ECE9DE", ink: "1E1F1F", muted: "55554F", accent: "154734", shape: "154734", soft: "DDD9CB", rule: "C9C4B4" },
  },
  mint: {
    name: "Deep green and mint",
    dark:  { bg: "07211A", ink: "E4F0E9", muted: "93B3A3", accent: "AFD2C0", shape: "AFD2C0", soft: "0F3328", rule: "1E4D3D" },
    light: { bg: "E4F0E9", ink: "07211A", muted: "3F5A4D", accent: "1E6349", shape: "1E6349", soft: "CFE3D7", rule: "B5D0C1" },
  },
  gold: {
    name: "Gold field",
    dark:  { bg: "07211A", ink: "F4F2EC", muted: "AFD2C0", accent: "FFB81C", shape: "FFB81C", soft: "16402F", rule: "2E5C49" },
    light: { bg: "FFB81C", ink: "0B2A1F", muted: "3B3410", accent: "0B2A1F", shape: "0B2A1F", soft: "F5A800", rule: "D99A0B" },
