// Slide roles in fixed series order, with the series' dark/light alternation.
const ROLES = [
  { id: "hook",        name: "Hook",                mode: "dark" },
  { id: "problem",     name: "Problem",             mode: "light" },
  { id: "insight",     name: "Insight",             mode: "dark" },
  { id: "application", name: "Application",         mode: "light" },
  { id: "takeaway",    name: "Takeaway",            mode: "dark" },
];

module.exports = { STAGE, FONTS, PALETTES, ROLES };

