#!/usr/bin/env node
// Contact sheet of a deck's five PowerPoint renders: node scripts/sheet.js 11 [12 ...]
// Writes decks/NN-slug/png/sheet.png (3 + 2 grid, 2400px wide). Needs ffmpeg.

const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const ROOT = path.join(__dirname, "..", "decks");
const want = process.argv.slice(2).map(a => String(a).padStart(2, "0"));
const dirs = fs.readdirSync(ROOT).filter(d => /^\d\d-/.test(d) && (!want.length || want.includes(d.slice(0, 2))));

for (const d of dirs) {
  const png = path.join(ROOT, d, "png");
  const inputs = [1, 2, 3, 4, 5].map(i => path.join(png, `slide${i}.png`));
  if (!inputs.every(f => fs.existsSync(f))) { console.log(`skip ${d}: renders missing`); continue; }
  const args = ["-loglevel", "error", "-y"];
  inputs.forEach(f => args.push("-i", f));
  args.push("-f", "lavfi", "-i", "color=c=0x777777:s=1600x900");
  args.push("-filter_complex", "[0][1][2]hstack=3[a];[3][4][5]hstack=3[b];[a][b]vstack,scale=2400:-1", path.join(png, "sheet.png"));
  execFileSync("ffmpeg", args);
  console.log(`ok   ${d}`);
}

